using System;

public class Utf8Inspector
{
    public static int GetUtf8SequenceLength(byte leadByte)
    {
        if ((leadByte & 0b1000_0000) == 0) return 1;
        if ((leadByte & 0b1110_0000) == 0b1100_0000) return 2;
        if ((leadByte & 0b1111_0000) == 0b1110_0000) return 3;
        if ((leadByte & 0b1111_1000) == 0b1111_0000) return 4;
        return -1; // Continuation byte atau format ilegal
    }

    public static void Main()
    {
        Console.WriteLine($"'A' (0x41): {GetUtf8SequenceLength(0x41)}");
        Console.WriteLine($"Emoji (0xF0): {GetUtf8SequenceLength(0xF0)}");
    }
}
